  const SearchPageResult({
    required this.totalCount,
    required this.results,
    required this.truncated,
    this.groupCount,
  });

  @override
  int get hashCode =>
      totalCount.hashCode ^
      results.hashCode ^
      truncated.hashCode ^
      groupCount.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SearchPageResult &&
          runtimeType == other.runtimeType &&
          totalCount == other.totalCount &&
          results == other.results &&
          truncated == other.truncated &&
          groupCount == other.groupCount;
}

class SearchResult {
  final String title;
  final String reference;
  final String text;
  final BigInt id;
  final BigInt segment;
  final bool isPdf;
  final String filePath;

  /// כמה תוצאות גולמיות מאוחדות בכרטיס הזה (1 = ללא איחוד). ראו
  /// [`ResultGrouping`]: בחיפוש מקובץ התוצאה היא נציג הקבוצה, והמונה
  /// הוא "נמצאו X תוצאות בטווח". כש-`truncated` דלוק המונה הוא תחתית —
  /// קבוצה שפונתה מהתקרה וחזרה מאבדת את חבריה המוקדמים.
  final int mergedCount;

  /// שאר חברות הקבוצה (ללא הנציג), עד [`MERGED_SIBLINGS_CAP`] — מיקומים
  /// בלבד, בלי snippet, כדי שהאפליקציה תוכל להציג "הרחב" ולקפוץ אליהן.
  /// `merged_count` עשוי לעלות על `merged.len() + 1` כשהקבוצה גדולה מהתקרה.
  final List<MergedSibling> merged;

  const SearchResult({
    required this.title,
    required this.reference,
    required this.text,
    required this.id,
    required this.segment,
    required this.isPdf,
    required this.filePath,
    required this.mergedCount,
    required this.merged,
  });

  @override
  int get hashCode =>
      title.hashCode ^
      reference.hashCode ^
      text.hashCode ^
      id.hashCode ^
      segment.hashCode ^
      isPdf.hashCode ^
      filePath.hashCode ^
      mergedCount.hashCode ^
      merged.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SearchResult &&
          runtimeType == other.runtimeType &&
          title == other.title &&
          reference == other.reference &&
          text == other.text &&
          id == other.id &&
          segment == other.segment &&
          isPdf == other.isPdf &&
          filePath == other.filePath &&
          mergedCount == other.mergedCount &&
          merged == other.merged;
}

/// טווח הקרבה הנדרש בין מילות שאילתה מרובת-מילים במסלול המתקדם.
enum SearchScope {
  /// ההתנהגות הקיימת: המילים מופיעות לפי סדר השאילתה, עם מגבלת
  /// מילים-ביניים לכל זוג סמוך (`distance` / `custom_spacing`).
  wordDistance,

  /// כל המילים באותה פסקה (מסמך אינדקס אחד = שורת ספר), בכל סדר ובכל
  /// מרחק. `distance`/`custom_spacing` אינם רלוונטיים במצב זה.
  sameParagraph,

  /// כל המילים תחת אותה כותרת (אותו בלוק `reference` — סעיף/פרק), גם
  /// כשהן פזורות על פני שורות שונות. התוצאות הן השורות שבתוך סעיף
  /// חותך שמכילות מילה מהשאילתה.
  sameSection,
}

/// One event of a combined stream search (`search_*_stream_with_counts`).
///
/// The first event carries the counts computed in the *same* index pass as
/// the ranked results (`total_count` + `book_counts`, with empty `results`);
/// every following event is a snippet-built results chunk (`None` counts).
/// One user search previously cost three full query executions — stream,
/// total count, and count-by-book — this collapses them into one.
class SearchStreamUpdate {
  /// Full hit count of the query; `Some` only on the first event.
  final int? totalCount;

  /// Live-document count per distinct `filePath`; `Some` only on the first
  /// event. Sums to `total_count`.
  final Map<String, int>? bookCounts;

  /// The results chunk (empty on the first, counts-bearing event).
  final List<SearchResult> results;

  /// `true` when a broad single-word query overflowed its collection budget
  /// and only the highest-priority term expansions were served, so both the
  /// counts and the results are partial (see [`SearchEngine::single_regex_term_query`]).
  /// Meaningful only on the first, counts-bearing event; always `false` on
  /// result chunks and on the mark-free exact/fuzzy paths, which never
  /// degrade this way (the vocalized exact/fuzzy paths can, like the
  /// advanced path). A *grouped* search on any path can also set it when
  /// the group cap overflows ([`GROUP_COLLECTOR_MAX_GROUPS`]) — then
  /// `group_count` is a lower bound while `total_count`/`book_counts`
  /// stay exact. The UI surfaces this as a "results may be partial —
  /// narrow the search" warning.
  final bool truncated;

  /// מספר הקבוצות הכולל כשהחיפוש רץ עם `grouping`; `Some` רק באירוע
  /// הראשון (נושא-הספירות), כמו `total_count`. `total_count` ו-
  /// `book_counts` נשארים ספירות גולמיות גם בחיפוש מקובץ.
  final int? groupCount;

  const SearchStreamUpdate({
    this.totalCount,
    this.bookCounts,
    required this.results,
    required this.truncated,
    this.groupCount,
  });

  @override
  int get hashCode =>
      totalCount.hashCode ^
      bookCounts.hashCode ^
      results.hashCode ^
      truncated.hashCode ^
      groupCount.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SearchStreamUpdate &&
          runtimeType == other.runtimeType &&
          totalCount == other.totalCount &&
          bookCounts == other.bookCounts &&
          results == other.results &&
          truncated == other.truncated &&
          groupCount == other.groupCount;
}

/// What [`SearchEngine::open_semantic_artifact`] opens: a semantic artifact built
/// on the build machine, and the model this device embeds queries with.
///
/// The artifact states the identity its vectors were built under, and opening
/// compares every field of it with this installation's. Nothing in this struct
/// is a value to type in: the corpus half is read from the corpus stamp inside
/// the open lexical index, and the model half is the model's published identity
/// file, the same one the artifact was built with.
///
/// The application's installation, and where each input points:
///
/// ```text
/// <root>/
/// ├── otzaria/                  the data folder
/// │   ├── seforim.db
/// │   └── <model>/              the model package
/// │       ├── seforim-embed-round2-int8.onnx      model_path
/// │       ├── tokenizer.json
/// │       └── model.json        the identity file: model_identity_json
/// ├── index/                    the lexical index, with its corpus stamp
/// └── <artifact>/               the vectors artifact: artifact_dir
/// ```
///
/// The artifact is a folder of its own beside `index/`, never inside it. ONNX
/// Runtime either ships with the application, which passes its path as
/// `onnx_runtime_path` (on macOS from inside the signed bundle), or sits in
/// `<model>/` beside the graph under the platform's file name, where it is found
/// without one; it is then the build for that machine's operating system and
/// architecture. Neither the identity file nor a runtime in that folder is part
/// of the model package's checksum.
class SemanticArtifactInput {
  /// The artifact directory, as `build_semantic_artifact` or
  /// `pack_semantic_artifact` wrote it: `manifest.json`, `payloads.json` and
  /// the payload files.
  final String artifactDir;

  /// The model queries are embedded with: an `.onnx` graph, with its
  /// `tokenizer.json` beside it, as for [`SemanticConfigInput::model_path`],
  /// and needing the ONNX Runtime library described there.
  final String modelPath;

  /// The text of the model's identity file: the JSON `ModelIdentity` the
  /// artifact was built with (`--model` of `build_semantic_artifact`), such as
  /// the sidecar's `config/models/meivin-round2-onnx/model.json` for the Meivin
  /// INT8 graph. Text rather than a path, so an application can ship it as an
  /// asset.
  ///
  /// Every field is compared: the recipe fields with the artifact's, and
  /// `model_checksum` and `embedding_backend` with the model at `model_path`
  /// once it has loaded, so an identity file that describes other weights is
  /// refused rather than trusted.
  final String modelIdentityJson;

  /// The artifact's digest as published outside it, when the release publishes
  /// one. Without it, opening still detects damage and a wrong artifact, but
  /// not one deliberately rebuilt to match.
  final String? publishedDigest;

  /// The ONNX Runtime library the application ships, as for
  /// [`SemanticConfigInput::onnx_runtime_path`]: the first place looked and,
  /// once passed, the only one; `None` for `OTZARIA_ONNX_RUNTIME` and then the
  /// file beside the graph. Opening loads the model, so a runtime that is
  /// missing or does not load is refused here, by kind. No identity field reads
  /// it, so it makes no artifact the wrong one; it is part of what a repeat call
  /// is compared on, since the process keeps the first runtime it loads.
  final String? onnxRuntimePath;

  const SemanticArtifactInput({
    required this.artifactDir,
    required this.modelPath,
    required this.modelIdentityJson,
    this.publishedDigest,
    this.onnxRuntimePath,
  });

  @override
  int get hashCode =>
      artifactDir.hashCode ^
      modelPath.hashCode ^
      modelIdentityJson.hashCode ^
      publishedDigest.hashCode ^
      onnxRuntimePath.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SemanticArtifactInput &&
          runtimeType == other.runtimeType &&
          artifactDir == other.artifactDir &&
          modelPath == other.modelPath &&
          modelIdentityJson == other.modelIdentityJson &&
          publishedDigest == other.publishedDigest &&
          onnxRuntimePath == other.onnxRuntimePath;
}

